import numpy as np
from scipy.optimize import least_squares
im=np.array([[58.5,97.8],[68.1,100.6],[75.1,90.2],[65.5,87.5],[67.2,38.7],[77.6,41.1],[84.2,35.8],[74.6,33.4]])
H=3;T=.4;W=1

def verts(theta):
 e=[0,T*np.sin(theta),-T*np.cos(theta)];f=[W,T*np.sin(theta),-T*np.cos(theta)];g=[W,0,0];h=[0,0,0];v=np.array([0,H*np.cos(theta),H*np.sin(theta)]);b=np.array([e,f,g,h]);return np.r_[b,b+v]
def camera(th):
 v=verts(th);X=np.c_[v,np.ones(8)];rows=[]
 for p,(u,w) in zip(X,im):
