 _,_,vv=np.linalg.svd(rows);P=vv[-1].reshape(3,4);P/=P[2,3];return P
def proj(v,P):
 q=np.c_[v,np.ones(len(v))]@P.T;return q[:,:2]/q[:,2,None]
for th in [.07,.14,.2]:
 P=camera(th);print('theta init',th,'P',P,'err', np.abs(proj(verts(th),P)-im).mean());print('final',np.round(proj(verts(np.pi/2),P),2).tolist())
